            if tok.value == "CREATE":
                return self.create()
            if tok.value == "DROP":
                self.next()
                self.expect_kw("TABLE")
                return DropTableStmt(self.ident())
            if tok.value == "INSERT":
                return self.insert()
            if tok.value == "SELECT":
                return self.select()
            if tok.value == "DELETE":
                self.next()
                self.expect_kw("FROM")
                table = self.ident()
                return DeleteStmt(table, self.opt_where())
        raise self.fail("statement")

    def opt_where(self) -> Expr | None:
        if self.is_kw("WHERE"):
            self.next()
            return self.expr()
        return None

